arguments:
{"script":"orig=$(find / -type f -name 'MyPersonalComputer.config' -print -quit 2>/dev/null)
if [ -z "$orig" ]; then echo "FILE_NOT_FOUND"; exit 1; fi
printf "%s\n" "$orig"
mv -- "$orig" . 2>/dev/null || { echo "MOVE_FAILED"; exit 1; }
[ -f ./MyPersonalComputer.config ] && echo "MOVED_TO_$(pwd)/MyPersonalComputer.config" || echo "MOVE_FAILED""}
